with latest as (select id, product_name, stock_qty, supplier_id from (select *, row_number() over (partition by supplier_id order by cost desc nulls first, id) as row_num from products) ranked where row_num = 1) select case when stock_qty >= 381 then 'PREMIUM' else 'STANDARD' end as stock_qty_tier, round(avg(stock_qty), 2) as avg_stock_qty, count(*) as cnt, bit_and(stock_qty) as stock_qty_bit_and, round(avg(stock_qty), 2) as avg_stock_qty_2, approx_percentile(stock_qty, array(0.25, 0.5, 0.75)) as stock_qty_quartiles from latest group by stock_qty_tier order by cnt desc;
